Definition bigW (sp t mb ms PA idx last nodes store : Z) : list (Z * Z) :=
  [(sp - 4096, sp); (0xb8b80, 0xb8b80 + 0x81030); (0x147408, 0x14740c); (t + 2800, t + 3169);
   (0x189848, 0x5d9890); (nodes, nodes + 1048576); (store, store + 8388608);
   (0xb4390, 0xb4399); (0xb43a8, 0xb43b8); (0xb45c0, 0xb45c4); (0xb45d8, 0xb45e8);
   (PA + 8 * idx, PA + 8 * idx + 8); (last + 24, last + 32); (mb, mb + ms); (shad mb, shad mb + shlen ms)].

